alter table voltes_game.catalog add column if not exists source_category text, add column if not exists image_path text, add column if not exists image_credit text, add column if not exists image_source text, add column if not exists image_license_url text;
alter table voltes_game.players add column if not exists appearance jsonb not null default '{}'::jsonb;
on conflict(id) do nothing;
